head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setUseFilter]<br/>Column 의 ID 를 사용하여 특정 Header Column 의 useFilter 속성을 설정합니다.",
    "validation" : [
        "GridView 의 headerFilter=true 이면 useFilter 속성은 무시됩니다.",
        "colId(필수) 파라미터로 useFilter 속성을 설정하려는 Column 의 Header Column ID 또는 Body Column ID 를 설정합니다.",
        "filter(선택) 파라미터를 true 로 설정 시, CustomFilter 기능을 활성화하고 Header Column 에 필터 버튼을 표시합니다.",
        "filter(선택) 를 true 로 설정 시, GridView 의 useFilterList=true 이면 CustomFilter 가 아닌 FilterList 기능이 활성화됩니다.",
        "filter(선택) 파라미터를 false 로 설정 시, CustomFilter 또는 FilterList 기능을 비활성화하고 Header Column 에 필터 버튼을 표시하지 않습니다.",
        "filter(선택) 파라미터 생략 시, 기본값 false 로 동작하여 필터 버튼을 표시하지 않습니다.",
        "useFilter 속성값이 성공적으로 변경된 경우 true 를 반환합니다.",
        "파라미터값이 유효하지 않거나 동일한 useFilter 속성값을 설정한 경우 false 를 반환합니다.",
        "setUseFilter() 메소드로 useFilter 속성이 true 에서 false 로 변경되면 필터 버튼의 display 만 'none' 으로 설정되고 DOM 은 제거되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 파라미터 기본 선택값 (정적 select1 은 초기 selectedIndex 미적용 → 명시적 setValue)
    par_colId.setValue("column2");
    par_filter.setValue("2");   // gdl_boolean : 2 = true

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 렌더 전제(con) : headerFilter, useFilterList (gdl_boolean getText → '' / 'true' / 'false')
    //  - useFilter 는 렌더 시 column1/column3 만 true, column2/column4 는 미설정(false) 로 인라인 고정.
    //  - sortable/showSortableImage 미설정(비-sortable) → useFilter=true Header 에 필터 아이콘 상시 표시.
    let vHeaderFilter = con_headerFilter.getText();
    let vUseFilterList = con_useFilterList.getText();

    let properties = {};
    if (vHeaderFilter === 'true') { properties.headerFilter = true; properties.defaultShowHeaderFilter = true; }
    else if (vHeaderFilter === 'false') { properties.headerFilter = false; }
    if (vUseFilterList === 'true') { properties.useFilterList = true; }

    let lblDesc = '[전제] column1·column3 Header = useFilter=true (필터 아이콘 有) / column2·column4 = useFilter=false (아이콘 無). Body ID = col1~col4. RowNum·RowStatus Header 는 필터 아이콘 없음.'
        + '\n headerFilter=' + (vHeaderFilter === '' ? '(미설정=false)' : vHeaderFilter) + ' / useFilterList=' + (vUseFilterList === '' ? '(미설정=false)' : vUseFilterList)
        + '\n[절차] par_colId·par_filter 선택 후 (setUseFilter). 반환값과 대상 Header 필터 버튼 존재/display 를 확인. 이어서 useFilter 컬럼 필터 아이콘 클릭해 팝업 연 뒤 (필터 팝업 유형 확인).'
        + '\n[확인] 반환값(true=변경성공 / false=무효값·동일값) 과 필터 버튼 display. useFilterList=true 면 filter=true 후 팝업이 FilterList. headerFilter=true 면 setUseFilter 무시(반환 undefined).';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // dataList 생성 (4행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    let cList = $c.gcm.createCList(properties);
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    // useFilter 혼재 Header Column(column1/column3=true, column2/column4=false) gridView 동적 생성
    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' rowNumVisible="true" rowStatusVisible="true" rowNumHeaderValue="No." rowStatusHeaderValue="St." checkAllType="false" id="" dataList="data:dlt_bind" style="width:600px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="setUseFilter 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="column1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    // headerFilter=true 일 때만 HeaderFilter 필터 행(filterColumn) 추가 → setUseFilter 무시 시 HeaderFilter 가 대신 표시됨을 확인
    if (vHeaderFilter === 'true') {
        s += '<w2:row style="" id="rowFilter">';
        s += '<w2:filterColumn width="130" style="" id="fcol1" value=""></w2:filterColumn>';
        s += '<w2:filterColumn width="130" style="" id="fcol2" value=""></w2:filterColumn>';
        s += '<w2:filterColumn width="130" style="" id="fcol3" value=""></w2:filterColumn>';
        s += '<w2:filterColumn width="*" style="" id="fcol4" value=""></w2:filterColumn>';
        s += '</w2:row>';
    }
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// [실행] setUseFilter : colId 컬럼의 useFilter 속성을 filter 값으로 설정.
//  - par_filter 가 (미설정) 이면 filter 인자를 생략 호출(기본값 false).
//  - headerFilter=true 면 무시(early return, 반환 undefined).
scwin.btn_setUseFilter_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");
    let colId = par_colId.getValue();
    let filterText = par_filter.getText();   // '' | 'true' | 'false'

    let r;
    let callDesc;
    if (filterText === '') {
        r = target1.setUseFilter(colId);                 // filter 생략 → 기본값 false
        callDesc = "setUseFilter(" + colId + ")  (filter 생략)";
    } else {
        let filter = (filterText === 'true');
        r = target1.setUseFilter(colId, filter);
        callDesc = "setUseFilter(" + colId + ", " + filter + ")";
    }

    // headerFilter=true 이면 useFilter 설정 무시(반환 undefined)
    if (target1.options.headerFilter === true) {
        scb.setReturnValue(callDesc + " 반환값 : " + r + "  (headerFilter=true 이므로 useFilter 설정 무시)");
        return;
    }

    // 대상 Header Column 의 필터 버튼(input.w2grid_customFilter_open) 상태 확인
    //  - colId 가 Body ID(col#) 이면 대응 Header ID(column#) 로 매핑하여 조회
    let headerId = colId;
    if (/^col[0-9]+$/.test(colId)) headerId = 'column' + colId.substring(3);
    let fBtn = document.querySelector("input.w2grid_customFilter_open[id$='_" + headerId + "_filter']");
    let btnState;
    if (!fBtn) {
        btnState = "필터 버튼 없음";
    } else {
        let disp = (fBtn.style.display === 'none') ? "none (숨김 / DOM 유지)" : "표시";
        btnState = "필터 버튼 존재 (display : " + disp + ")";
    }

    scb.setReturnValue(callDesc + " 반환값 : " + r + "  /  " + btnState);
}



// [확인] 필터 팝업 유형 : 사용자가 useFilter=true 컬럼의 필터 아이콘을 클릭해 팝업을 연 뒤 실행.
//  useFilterList=true 면 FilterList(.w2grid_customFilter_list), false 면 CustomFilter(.w2grid_customFilter).
scwin.btn_checkPopup_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");

    scb.setReturnValue("[옵션] useFilterList : " + target1.options.useFilterList);

    let listPopup = document.querySelector(".w2grid_customFilter_list");
    let customPopup = document.querySelector(".w2grid_customFilter");
    let hasList = !!listPopup;
    let hasCustom = !!customPopup;
    if (!hasList && !hasCustom) {
        scb.setReturnValue("열린 필터 팝업이 없습니다. useFilter 컬럼 헤더의 필터 아이콘을 먼저 클릭하세요.");
    } else {
        scb.setReturnValue("FilterList 팝업(.w2grid_customFilter_list) 표시 : " + hasList + " / CustomFilter 팝업(.w2grid_customFilter) 표시 : " + hasCustom);
    }
}
